package com.quincaisoft.tenders.application;import com.quincaisoft.finance.api.PeriodCloseGuard;import jakarta.persistence.EntityManager;import org.springframework.stereotype.Component;import java.time.LocalDate;
@Component public class CashPeriodGuard implements PeriodCloseGuard {private final EntityManager em;public CashPeriodGuard(EntityManager em){this.em=em;}public String domain(){return "cash";}public void verifyCanClose(LocalDate start,LocalDate end){long n=em.createQuery("select count(r) from CashSessionEntity r where r.status='OPEN' and r.businessDate between :start and :end",Long.class).setParameter("start",start).setParameter("end",end).getSingleResult();if(n>0)throw new IllegalStateException("Open cash sessions prevent period closure");}}
